para calcular e consolidar cada linha e também produzir um objeto agregado por campanha e geral.

Fórmulas

* CPC = spend / clicks
* CPL = spend / leads
* CPR = spend / purchases
* CTR% = (clicks / impressions) \* 100
* Conversão funil 1→2 = leads\_stage\_2 / leads\_stage\_1
* Conversão final = leads\_final / leads\_stage\_1

Exemplo de código (Function: KPIs)

```function safeDiv(a,b){ return b>0 ? a/b : 0; }

const grouped = {};
const out = items.map(i => {
  const r = i.json;

  const cpc = safeDiv(r.spend, r.clicks);
  const cpl = safeDiv(r.spend, r.leads);
  const cpr = safeDiv(r.spend, r.purchases);
  // Sheets campos:
  const s1 = Number(r.leads_stage_1 || 0);
  const s2 = Number(r.leads_stage_2 || 0);
  const sf = Number(r.leads_final || 0);
  const conv12 = safeDiv(s2, s1);
  const convFinal = safeDiv(sf, s1);

  const row = {
    date: r.date,
    campaign_id: r.campaign_id,
    campaign_name: r.campaign_name,
    impressions: Number(r.impressions || 0),
    clicks: Number(r.clicks || 0),
    spend: Number(r.spend || 0),
    leads: Number(r.leads || 0),
    purchases: Number(r.purchases || 0),
    ctr: Number(r.ctr || 0),
    budget_allocated: Number(r.budget_allocated || 0),
    leads_stage_1: s1,
    leads_stage_2: s2,
    leads_final: sf,
    kpi: { cpc, cpl, cpr, conv12, convFinal }
  };

  const key = r.campaign_id || r.campaign_name || 'unknown';
  if(!grouped[key]){
    grouped[key] = {
      campaign_id: r.campaign_id,
      campaign_name: r.campaign_name,
      impressions:0, clicks:0, spend:0, leads:0, purchases:0,
      s1:0, s2:0, sf:0
    };
  }
  grouped[key].impressions += row.impressions;
  grouped[key].clicks += row.clicks;
  grouped[key].spend += row.spend;
  grouped[key].leads += row.leads;
  grouped[key].purchases += row.purchases;
  grouped[key].s1 += s1;
  grouped[key].s2 += s2;
  grouped[key].sf += sf;

  return { json: row };
});

// cria resumo por campanha e geral
const summary = Object.values(grouped).map(g => ({
  campaign_id: g.campaign_id,
  campaign_name: g.campaign_name,
  impressions: g.impressions,
  clicks: g.clicks,
  spend: g.spend,
  leads: g.leads,
  purchases: g.purchases,
  ctr: safeDiv(g.clicks, g.impressions) * 100,
  cpc: safeDiv(g.spend, g.clicks),
  cpl: safeDiv(g.spend, g.leads),
  cpr: safeDiv(g.spend, g.purchases),
  conv12: safeDiv(g.s2, g.s1),
  convFinal: safeDiv(g.sf, g.s1)
}));

const total = summary.reduce((t,g)=>({
  impressions: t.impressions + g.impressions,
  clicks: t.clicks + g.clicks,
  spend: t.spend + g.spend,
  leads: t.leads + g.leads,
  purchases: t.purchases + g.purchases
}), {impressions:0,clicks:0,spend:0,leads:0,purchases:0});

const totalKPIs = {
  ctr: safeDiv(total.clicks, total.impressions) * 100,
  cpc: safeDiv(total.spend, total.clicks),
  cpl: safeDiv(total.spend, total.leads),
  cpr: safeDiv(total.spend, total.purchases)
};

return [
  { json: { rows: items.map(i=>i.json) } },             // saída 1: linhas detalhadas
  { json: { summary } },                                // saída 2: resumo por campanha
  { json: { total: total, totalKPIs } }                 // saída 3: totais gerais
];```

Configure este Function como Multiple Outputs = 3 para usar nos próximos nós.

